const titleDescriptors=['Döner ve Sallanır Mekanizmalı','Sürgülü Aynalı','Aynalı Sürgülü','Sürgü Aynalı','İki Çekmeceli','Dört Çekmeceli','İç Çekmeceli','İki Kapaklı','Sürgü Kapaklı','Sürgü Kapılı','Tek Raflı','Tek Kişilik','Çift Kişilik','Tam Kapaklı','Tek Kapaklı','Tek Çekmeceli','Çamaşır Sepetli','Metal Ayaklı','Döner Mekanizmalı','Yükseklik Ayarlı','Ara Bölmeli','Orta Bölmeli','Sürgülü','Aynalı','Kapaklı','Çekmeceli','Kilitli','Raflı','Bazalı','Dikdörtgen','Kare','Katlanabilir','Tepsili','Modüler','Dekoratif','Geniş','Masif','Tekerlekli','Çok Amaçlı','Açılır','Bölmeli','File Sırtlı','Metal Gövdeli','Döner','ve'];
function naturalTitle(text,locale){
  let noun;let found;
  for(const candidate of titleNouns){const match=new RegExp(`(?<![\\p{L}])${escapeRegex(candidate)}(?![\\p{L}])`,'iu').exec(text);if(match){noun=candidate;found=match;break;}}
  if(!found)return null;
  let prefix=text.slice(0,found.index);const suffix=text.slice(found.index+found[0].length);const attributes=[];
  prefix=prefix.replace(/(\d+)\s*(Raflı|Çekmeceli|Kapaklı|Kapılı|Bölmeli|Katlı|Kişilik|Tabureli|Askılı)/giu,(_,n,kind)=>{
    const type=normalize(kind);const values={
      'raflı':local(`${n} ${n==='1'?'shelf':'shelves'}`,`полки: ${n}`,`رفوف: ${n}`,locale),'çekmeceli':local(`${n} ${n==='1'?'drawer':'drawers'}`,`ящики: ${n}`,`أدراج: ${n}`,locale),'kapaklı':local(`${n} ${n==='1'?'door':'doors'}`,`двери: ${n}`,`أبواب: ${n}`,locale),'kapılı':local(`${n} ${n==='1'?'door':'doors'}`,`двери: ${n}`,`أبواب: ${n}`,locale),'bölmeli':local(`${n} ${n==='1'?'compartment':'compartments'}`,`отделения: ${n}`,`حجرات: ${n}`,locale),'katlı':local(`${n} tiers`,`ярусы: ${n}`,`مستويات: ${n}`,locale),'kişilik':local(`${n} seats`,`места: ${n}`,`مقاعد: ${n}`,locale),'tabureli':local(`${n} stools`,`табуреты: ${n}`,`مقاعد: ${n}`,locale),'askılı':local(`${n} coat hooks`,`крючки: ${n}`,`خطافات: ${n}`,locale)};
    attributes.push(values[type]);return ' ';
  });
  for(const descriptor of titleDescriptors){const re=new RegExp(`(?<![\\p{L}])${escapeRegex(descriptor)}(?![\\p{L}])`,'giu');if(re.test(prefix)){prefix=prefix.replace(re,' ');if(descriptor!=='ve')attributes.push(exact.get(normalize(descriptor))?.[locale]??descriptor);}}
  const model=prefix.replace(/\s+/g,' ').trim();const modelResult=lineTranslation(model,locale,{kind:'fragment'});const tail=lineTranslation(suffix,locale,{kind:'fragment'});
  const core=exact.get(normalize(noun))?.[locale];if(!core)return null;
  const details=attributes.map(value=>value.charAt(0).toLocaleLowerCase(locale)+value.slice(1));
  const tailContent=tail.text.replace(/^[\s\-–—]+/u,'').replace(/-(?=[^\d])/gu,' / ');
  const rendered=`${modelResult.text}${modelResult.text?' ':''}${core}${details.length?', '+details.join(', '):''}${tailContent?' — ':''}${tailContent}`.replace(/\s+/g,' ').trim();
  return {text:rendered,complete:modelResult.complete&&tail.complete};
}

function lineTranslation(raw,locale,{kind}={}) {
  let text=String(raw??'').replace(/[\u200b-\u200d\ufeff]/g,'').trim();
  if(!text||locale==='tr')return {text,complete:true};
  if(!locales.includes(locale))locale='en';
  if(kind==='title'){const natural=naturalTitle(text,locale);if(natural)return natural;}
  let key=normalize(text); let hit=exact.get(key);
  if(hit)return {text:hit[locale],complete:true};
  for(const [from,to]of aliases)text=text.replace(new RegExp(escapeRegex(from),'giu'),to);
  key=normalize(text);hit=exact.get(key);if(hit)return {text:hit[locale],complete:true};
  let match=text.match(/^Ürün\s+(\d+)\s+koliden\s+oluşmaktadır\.?$/iu);
  if(match)return {text:local(`${match[1]} package${match[1]==='1'?'':'s'}`,`Количество упаковок: ${match[1]}`,`عدد العبوات: ${match[1]}`,locale),complete:true};
  match=text.match(/^(\d+)\s*yıl$/iu);
  if(match)return {text:local(`${match[1]} years`,`${match[1]} лет`,`${match[1]} سنوات`,locale),complete:true};
  match=text.match(/^(?:Ürünlerimiz\s+)?[Üü]retim ve işçilik hatalarına karşı\s+(\d+)\s+yıl garantilidir\.?$/iu);
  if(match)return {text:local(`The manufacturer provides a ${match[1]}-year warranty against manufacturing and workmanship defects.`,`Гарантия производителя на дефекты изготовления и сборки: ${match[1]} лет.`,`ضمان الشركة المصنعة لمدة ${match[1]} سنوات ضد عيوب التصنيع والصناعة.`,locale),complete:true};
  match=text.match(/^[Üü]retim ve işçilik hatalarına karşı (\d+) yıl garanti belgesine sahiptir ve Avrupa TÜV CERT ISO 9001 kalite standardına uygun üretilmiştir\.?$/iu);
  if(match)return {text:local(`The manufacturer states a ${match[1]}-year warranty against manufacturing and workmanship defects and production to the European TÜV CERT ISO 9001 quality standard.`,`Производитель заявляет гарантию ${match[1]} лет на производственные дефекты и соответствие европейскому стандарту качества TÜV CERT ISO 9001.`,`تذكر الشركة المصنعة ضماناً لمدة ${match[1]} سنوات ضد عيوب التصنيع والإنتاج وفق معيار الجودة الأوروبي TÜV CERT ISO 9001.`,locale),complete:true};
  if(/^\d/.test(text)&&/Genişlik\s*x\s*Yükseklik\s*x\s*Derinlik/iu.test(text))return {text:text.replace(/Genişlik\s*x\s*Yükseklik\s*x\s*Derinlik/giu,local('Width × Height × Depth','Ширина × Высота × Глубина','العرض × الارتفاع × العمق',locale)),complete:true};
  if(/^[\d\s.,x×X/()\-–]+(?:cm|mm|kg|m²|m3|m³|inç)?$/iu.test(text))return {text,complete:true};
  match=text.match(/^(\d+(?:\s*[-–]\s*\d+)?)\s+çift ayakkabı,?\s*terlik kapasite(?:si|li)\.?$/iu);
  if(match)return {text:local(`Capacity: ${match[1]} pairs of shoes or slippers`,`Вместимость: ${match[1]} пар обуви или тапочек`,`السعة: ${match[1]} أزواج من الأحذية أو النعال`,locale),complete:true};
  match=text.match(/^(\d+)\s+adet\s+(.+?)[.]?$/iu);
  if(match){
    const nouns={
      'geniş raf':['wide shelves','широких полок','رفوف واسعة'],'estetik görünüşlü raf':['shelves','полок','رفوف'],'raf':['shelves','полок','رفوف'],'hareketli raf':['adjustable shelves','регулируемых полок','رفوف قابلة للتعديل'],'sabit raf':['fixed shelves','стационарных полок','رفوف ثابتة'],'çekmece':['drawers','ящиков','أدراج'],'geniş çekmece':['wide drawers','широких ящиков','أدراج واسعة'],'derin çekmece':['deep drawers','глубоких ящиков','أدراج عميقة'],'dar çekmece':['narrow drawers','узких ящиков','أدراج ضيقة'],'kilitli çekmece':['lockable drawers','запираемых ящиков','أدراج بقفل'],'kapak':['doors','дверей','أبواب'],'düşer kapak':['tilt-out doors','откидных дверей','أبواب قلابة'],'geniş bölme':['spacious compartments','вместительных отделений','حجرات واسعة'],'kapaklı bölme':['enclosed compartments','закрытых отделений','حجرات مغلقة'],'kullanışlı açık bölme':['practical open compartments','практичных открытых отделений','حجرات مفتوحة عملية'],'dayanıklı metal elbise askılığı':['durable metal clothes rails','прочных металлических штанг для одежды','قضبان معدنية متينة لتعليق الملابس'],'kapakta boy aynası':['full-length door mirrors','зеркал в полный рост на двери','مرايا بطول الجسم على الأبواب'],'krom kaplama düğme kulp':['chrome-plated knob handles','хромированных ручек-кнопок','مقابض دائرية مطلية بالكروم'],'üç başlı estetik ve sağlam metal askı aparatı':['sturdy triple metal coat hooks','прочных тройных металлических крючков','خطافات ملابس معدنية ثلاثية متينة'],
    };
    const noun=nouns[normalize(match[2])];
    if(noun)return {text:local(`${match[1]} ${noun[0]}`,`${match[1]} ${noun[1]}`,`${match[1]} ${noun[2]}`,locale),complete:true};
  }
  match=text.match(/^Maksimum\s+(\d+)\s+INC televizyon kapasitesi$/iu);
  if(match)return {text:local(`For TVs up to ${match[1]} inches`,`Для телевизоров до ${match[1]} дюймов`,`لأجهزة تلفاز حتى ${match[1]} بوصة`,locale),complete:true};
  match=text.match(/^(\d+)\s*mm\s+Yonga Levha$/iu);
  if(match)return {text:local(`${match[1]} mm particleboard`,`${match[1]} мм ДСП`,`خشب حبيبي بسماكة ${match[1]} مم`,locale),complete:true};
  // Term translation preserves numerical dimensions and model names. Residual Turkish is not marked complete.
  let translated=text; const placeholders=[];
  const protect=value=>{const id=placeholders.length;placeholders.push(value);return `⟦${id}⟧`;};
  translated=translated.replace(/\(\s*G\s*x\s*Y\s*x\s*D\s*\)/giu,()=>protect(local('(W×H×D)','(Ш×В×Г)','(العرض×الارتفاع×العمق)',locale)));
  translated=translated.replace(/(\d+)\s*(?:adet\s*)?(Raflı|Çekmeceli|Kapaklı|Kapılı|Bölmeli|Katlı)/giu,(_,n,type)=>{
    const map={'raflı':local(`${n}-shelf`,`с ${n} полками`,`بـ ${n} رفوف`,locale),'çekmeceli':local(`${n}-drawer`,`с ${n} ящиками`,`بـ ${n} أدراج`,locale),'kapaklı':local(`${n}-door`,`с ${n} дверцами`,`بـ ${n} أبواب`,locale),'kapılı':local(`${n}-door`,`с ${n} дверцами`,`بـ ${n} أبواب`,locale),'bölmeli':local(`${n}-compartment`,`с ${n} отделениями`,`بـ ${n} حجرات`,locale),'katlı':local(`${n}-tier`,`${n}-ярусный`,`بـ ${n} مستويات`,locale)};
    return protect(map[normalize(type)]);
  });
  translated=translated.replace(/(\d+)\s*['’]?(?:li|lı|lü|lu)(?![\p{L}])/giu,(_,n)=>protect(local(`set of ${n}`,`набор из ${n}`,`طقم من ${n}`,locale)));
  for(const row of terms){
    const re=new RegExp(`(?<![\\p{L}])${escapeRegex(row[0]).replace(/\s+/g,'\\s+')}(?![\\p{L}])`,'giu');
    translated=translated.replace(re,()=>protect(row[indexFor(locale)]));
  }
  const residue=translated.replace(/⟦\d+⟧/g,' ').replace(/\b\d+(?:[.,]\d+)?(?:x\d+(?:[.,]\d+)?)*\b/gi,' ').replace(/[\d.,;:/()\-–×+%'"&=]/g,' ');
  const residualWords=residue.match(/[\p{L}]+/gu)??[];
  const complete=residualWords.every(word=>properNames.has(normalize(word)));
  translated=translated.replace(/⟦(\d+)⟧/g,(_,index)=>placeholders[Number(index)]);
  if(kind==='title')translated=translated.replace(/\s+/g,' ').trim();
  return {text:!complete&&['specValue','specLabel','description'].includes(kind)?String(raw??'').trim():translated,complete};
}

function result(text,locale,options={}) {
  if(locale==='tr')return {text:String(text??''),complete:true};
  const lines=String(text??'').split(/\r?\n/).map(line=>lineTranslation(line,locale,options));
  return {text:lines.map(line=>line.text).join('\n'),complete:lines.every(line=>line.complete)};
}

export function translateText(text,locale,options={}) {return result(text,locale,options).text;}
export function translationIsComplete(text,locale,options={}) {return result(text,locale,options).complete;}
export function translateCategory(name,id,locale) {return categories.get(String(id))?.[locales.includes(locale)?locale:'en']??translateText(name??String(id),locale,{kind:'category'});}
export function categoryTranslationIsComplete(name,id,locale) {return categories.has(String(id))||translationIsComplete(name,locale,{kind:'category'});}
